INSERT INTO public.quiz_questions (id, module_id, kind, prompt, options, correct, explanation, source, critical, topic) VALUES
  ('forest_fruit', 'forest', 'single', 'Ви зрізали білий гриб. Що сталося з самим грибом як організмом?', '[{"id": "a", "text": "Загинув повністю"}, {"id": "b", "text": "Живе далі під землею"}, {"id": "c", "text": "Розсипався на спори"}, {"id": "d", "text": "Виросте з насіння знову"}]'::jsonb, '["b"]'::jsonb, 'Те, що ми збираємо, — лише плодове тіло. Сам гриб — грибниця: тонкі нитки в ґрунті чи деревині. Вона живе роками й дає нові гриби.', 'загальна мікологія (шкільний курс біології); довідник: моховик зелений («білі тяжі міцелію біля основи ніжки»)', false, 'mycelium'),
  ('forest_tf_seeds', 'forest', 'single', 'Правда чи міф: гриби розмножуються насінням, як рослини.', '[{"id": "a", "text": "Правда"}, {"id": "b", "text": "Міф"}]'::jsonb, '["b"]'::jsonb, 'Міф. Насіння в грибів немає — вони розмножуються спорами. Колір спорового порошку навіть указано в картках довідника.', 'загальна мікологія (шкільний курс біології); довідник (поле «Споровий порошок»)', false, 'mycelium'),
  ('forest_tf_small', 'forest', 'single', 'Правда чи міф: гриб, який ви бачите в лісі, — лише мала частина всього гриба.', '[{"id": "a", "text": "Правда"}, {"id": "b", "text": "Міф"}]'::jsonb, '["a"]'::jsonb, 'Правда. Основна частина — грибниця під землею чи в деревині. Вона може займати велику площу, а гриби — лише її «плоди».', 'загальна мікологія (шкільний курс біології)', false, 'mycelium'),
  ('forest_group', 'forest', 'single', 'Ви знайшли один білий гриб. Що найрозумніше зробити далі?', '[{"id": "a", "text": "Іти шукати в інший ліс"}, {"id": "b", "text": "Оглянути 5–10 м навколо"}, {"id": "c", "text": "Чекати, поки виросте ще"}, {"id": "d", "text": "Шукати лише під тим деревом"}]'::jsonb, '["b"]'::jsonb, 'Гриби з однієї грибниці ростуть групами, «родинами». Тому поруч із першою знахідкою часто є ще.', 'довідник: білий гриб («Порада шукачу»: огляньте 5–10 м навколо)', false, 'mycelium'),
  ('forest_ring', 'forest', 'single', 'На луці гриби виросли рівним колом. Чому так?', '[{"id": "a", "text": "Хтось їх так посадив"}, {"id": "b", "text": "Грибниця росте від центру"}, {"id": "c", "text": "Там раніше стояв стіг сіна"}, {"id": "d", "text": "Так падає тінь від дерев"}]'::jsonb, '["b"]'::jsonb, 'Це «відьмине кільце»: грибниця щороку розростається від центру на всі боки, а гриби з''являються на її краю.', 'довідник: опеньок луговий, говорушка руда («утворює відьмині кільця»)', false, 'mycelium'),
  ('forest_order_grow', 'forest', 'order', 'Розставте по порядку, як з''являється гриб.', '[{"id": "a", "text": "Спора проростає ниткою"}, {"id": "b", "text": "Нитки сплітаються в грибницю"}, {"id": "c", "text": "Проходить теплий дощ"}, {"id": "d", "text": "Із грибниці виростає гриб"}]'::jsonb, '["a", "b", "c", "d"]'::jsonb, 'Спершу зі спори виростає нитка, з ниток — грибниця. Гриби вона дає, коли є волога й тепло: за довідником — через 2–4 дні після теплого дощу.', 'загальна мікологія (шкільний курс біології); довідник («Ідеальний момент: через 2–4 дні після теплого дощу»)', false, 'mycelium'),
  ('forest_trade_gets', 'forest', 'single', 'Білий гриб і дуб живуть у союзі. Що гриб отримує від дерева?', '[{"id": "a", "text": "Воду з глибини"}, {"id": "b", "text": "Цукри з листя"}, {"id": "c", "text": "Захист від тварин"}, {"id": "d", "text": "Тінь і прохолоду"}]'::jsonb, '["b"]'::jsonb, 'Союз гриба з корінням дерева називають мікоризою. Дерево ділиться з грибом цукрами, які робить листя на світлі.', 'загальна мікологія (шкільний курс біології); довідник: білий гриб («з корінням яких гриб живе у симбіозі»)', false, 'partners'),
  ('forest_trade_gives', 'forest', 'single', 'А що в цьому союзі отримує дерево від гриба?', '[{"id": "a", "text": "Воду й мінерали"}, {"id": "b", "text": "Цукри й крохмаль"}, {"id": "c", "text": "Захист від вітру"}, {"id": "d", "text": "Нічого, гриб — паразит"}]'::jsonb, '["a"]'::jsonb, 'Грибниця, як губка, збирає з ґрунту воду й мінеральні речовини і передає їх корінню. Обом вигідно.', 'загальна мікологія (шкільний курс біології)', false, 'partners'),
  ('forest_farm', 'forest', 'single', 'Чому білий гриб не вирощують на фермах, як гливу чи печерицю?', '[{"id": "a", "text": "Потрібне живе дерево"}, {"id": "b", "text": "Він росте надто повільно"}, {"id": "c", "text": "Це заборонено законом"}, {"id": "d", "text": "Ніхто не пробував"}]'::jsonb, '["a"]'::jsonb, 'Білому грибу потрібен союз із корінням живого дерева. Глива ж росте на деревині, а печериця — на перегної, тож їх легко вирощувати.', 'загальна мікологія (шкільний курс біології); довідник: білий гриб, глива звичайна', false, 'partners'),
  ('forest_tf_cut', 'forest', 'single', 'Правда чи міф: якщо в гаю вирубали всі берези, підберезники там ростимуть так само.', '[{"id": "a", "text": "Правда"}, {"id": "b", "text": "Міф"}]'::jsonb, '["b"]'::jsonb, 'Міф. Підберезник росте під березами в союзі з ними. Немає дерева — грибниці нема чим живитися.', 'довідник: підберезник звичайний («під березами»)', false, 'partners'),
  ('forest_multi_partner', 'forest', 'multi', 'Які з цих грибів живуть у союзі з деревами? Оберіть усе правильне.', '[{"id": "a", "text": "Лисичка"}, {"id": "b", "text": "Груздь справжній"}, {"id": "c", "text": "Глива звичайна"}, {"id": "d", "text": "Печериця польова"}]'::jsonb, '["a", "b"]'::jsonb, 'Лисичка утворює мікоризу з деревами, груздь — із березою. Глива живиться деревиною, а печериця польова росте на луках і пасовищах.', 'довідник: лисичка справжня, груздь справжній, глива звичайна, печериця польова', false, 'partners'),
  ('forest_tf_truffle', 'forest', 'single', 'Правда чи міф: трюфель теж живе в союзі з деревами.', '[{"id": "a", "text": "Правда"}, {"id": "b", "text": "Міф"}]'::jsonb, '["a"]'::jsonb, 'Правда. Трюфель літній утворює мікоризу з листяними деревами на вапнякових ґрунтах.', 'довідник: трюфель літній', false, 'partners'),
  ('forest_birch', 'forest', 'single', 'Ви в чистому березняку. Кого тут шукати марно?', '[{"id": "a", "text": "Підберезник"}, {"id": "b", "text": "Груздь справжній"}, {"id": "c", "text": "Маслюк модриновий"}, {"id": "d", "text": "Сироїжку біло-чорну"}]'::jsonb, '["c"]'::jsonb, 'Маслюк модриновий росте виключно під модринами. А підберезник, груздь справжній і сироїжка біло-чорна — якраз під березою.', 'довідник: маслюк модриновий, підберезник, груздь справжній, сироїжка біло-чорна', false, 'trees'),
  ('forest_tf_larch', 'forest', 'single', 'Правда чи міф: маслюк модриновий можна знайти в міському парку.', '[{"id": "a", "text": "Правда"}, {"id": "b", "text": "Міф"}]'::jsonb, '["a"]'::jsonb, 'Правда. Він росте під модринами — і в парках, садах та алеях, де їх висадили.', 'довідник: маслюк модриновий', false, 'trees'),
  ('forest_young_pine', 'forest', 'single', 'Де найвищий шанс знайти маслюки й рижики?', '[{"id": "a", "text": "У молодому сосняку"}, {"id": "b", "text": "У старій діброві"}, {"id": "c", "text": "У вільшанику на болоті"}, {"id": "d", "text": "У березовому гаю"}]'::jsonb, '["a"]'::jsonb, 'Маслюк пізній любить соснові ліси, особливо молоді. Рижик справжній — так само молоді соснові ліси.', 'довідник: маслюк пізній, рижик справжній', false, 'trees'),
  ('forest_white_trees', 'forest', 'multi', 'Біля яких дерев варто шукати білий гриб? Оберіть усе правильне.', '[{"id": "a", "text": "Біля дуба"}, {"id": "b", "text": "Біля сосни"}, {"id": "c", "text": "Біля берези"}, {"id": "d", "text": "На трухлявому пні"}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Білий гриб живе в союзі з корінням багатьох дерев: дуба, бука, берези, граба, сосни, ялини. Росте на ґрунті, а не на пнях.', 'довідник: білий гриб («Де росте?»)', false, 'trees'),
  ('forest_odd_pine', 'forest', 'single', 'Хто з цих грибів НЕ росте під сосною?', '[{"id": "a", "text": "Маслюк пізній"}, {"id": "b", "text": "Рижик справжній"}, {"id": "c", "text": "Польський гриб"}, {"id": "d", "text": "Підберезник"}]'::jsonb, '["d"]'::jsonb, 'Підберезник — під березою. Маслюк пізній, рижик і польський гриб ростуть у соснових чи мішаних із сосною лісах.', 'довідник: маслюк пізній, рижик справжній, польський гриб, підберезник', false, 'trees'),
  ('forest_sand', 'forest', 'single', 'Ви в сухому сосновому бору на піску. Який гриб тут найімовірніший?', '[{"id": "a", "text": "Польський гриб"}, {"id": "b", "text": "Груздь справжній"}, {"id": "c", "text": "Підосичник"}, {"id": "d", "text": "Глива звичайна"}]'::jsonb, '["a"]'::jsonb, 'Польський гриб любить хвойні ліси з сосною на піщаному ґрунті. Груздь — вологий мох під березами, підосичник — під осикою, глива — на деревині.', 'довідник: польський гриб, груздь справжній, підосичник, глива звичайна', false, 'trees'),
  ('forest_tf_stump', 'forest', 'single', 'Правда чи міф: гриби, що ростуть на пні, — це завжди опеньки.', '[{"id": "a", "text": "Правда"}, {"id": "b", "text": "Міф"}]'::jsonb, '["b"]'::jsonb, 'Міф. На пнях ростуть і опеньок осінній, і отруйний опеньок сірчано-жовтий, і глива. Місце росту гриб не визначає.', 'довідник: опеньок осінній, опеньок сірчано-жовтий, глива звичайна', false, 'wood'),
  ('forest_tinder', 'forest', 'single', 'Трутовик сірчано-жовтий росте на живому дубі. Що він робить дереву?', '[{"id": "a", "text": "Допомагає рости"}, {"id": "b", "text": "Руйнує деревину"}, {"id": "c", "text": "Захищає від комах"}, {"id": "d", "text": "Нічого не робить"}]'::jsonb, '["b"]'::jsonb, 'Трутовик — паразит: він спричиняє гниль деревини живого дерева, а потім живиться вже мертвою.', 'довідник: трутовик сірчано-жовтий («паразит і сапротроф, спричиняє буру гниль»)', false, 'wood'),
  ('forest_multi_wood', 'forest', 'multi', 'Які з цих грибів ростуть на деревині, а не на ґрунті? Оберіть усе правильне.', '[{"id": "a", "text": "Глива звичайна"}, {"id": "b", "text": "Опеньок осінній"}, {"id": "c", "text": "Лисичка справжня"}, {"id": "d", "text": "Підберезник"}]'::jsonb, '["a", "b"]'::jsonb, 'Глива — на стовбурах дерев, опеньок осінній — на пнях, стовбурах і корінні. Лисичка й підберезник ростуть на ґрунті.', 'довідник: глива звичайна, опеньок осінній, лисичка справжня, підберезник', false, 'wood'),
  ('forest_tf_winter', 'forest', 'single', 'Правда чи міф: після перших морозів гриби в лісі вже не ростуть зовсім.', '[{"id": "a", "text": "Правда"}, {"id": "b", "text": "Міф"}]'::jsonb, '["b"]'::jsonb, 'Міф. Зимовий опеньок росте з вересня до грудня, а в м''яку зиму й до січня — на пнях і стовбурах тополь, верб, осик.', 'довідник: зимовий опеньок', false, 'wood'),
  ('forest_oyster_ground', 'forest', 'single', 'Схожий на гливу гриб росте на землі, а біля ніжки — білий «мішечок». Що це означає?', '[{"id": "a", "text": "Це глива, що впала з дерева"}, {"id": "b", "text": "Це не глива — не брати"}, {"id": "c", "text": "Це молода глива, ще росте"}, {"id": "d", "text": "Це глива, що виросла з кореня"}]'::jsonb, '["b"]'::jsonb, 'Глива росте на деревині, має бічну ніжку і ніколи не має «мішечка» (вольви). Гриб на землі з вольвою може бути блідою поганкою.', 'довідник: бліда поганка («з ким можна сплутати: глива — росте на деревині, немає вольви»)', false, 'wood'),
  ('forest_where_oyster', 'forest', 'single', 'Де шукати гливу?', '[{"id": "a", "text": "На стовбурах дерев"}, {"id": "b", "text": "У моху під соснами"}, {"id": "c", "text": "На луці серед трави"}, {"id": "d", "text": "На піску на галявині"}]'::jsonb, '["a"]'::jsonb, 'Глива росте на стовбурах листяних дерев — живих, але ослаблених, — на пнях і мертвій деревині, часто «поверхами».', 'довідник: глива звичайна', false, 'wood'),
  ('forest_tf_dead', 'forest', 'single', 'Правда чи міф: деякі гриби живляться мертвою деревиною й опалим листям і так «прибирають» ліс.', '[{"id": "a", "text": "Правда"}, {"id": "b", "text": "Міф"}]'::jsonb, '["a"]'::jsonb, 'Правда. Таких грибів багато: опеньок літній живе на мертвій деревині, маразмії — на опалому листі. Вони перетворюють рештки на ґрунт.', 'довідник: опеньок літній («сапротроф на мертвій деревині»), маразмій листовий', false, 'wood'),
  ('forest_meadow', 'forest', 'single', 'Де найімовірніше знайти печерицю польову?', '[{"id": "a", "text": "На луці, пасовищі"}, {"id": "b", "text": "У темному ялиннику"}, {"id": "c", "text": "На стовбурі дерева"}, {"id": "d", "text": "У моху під березою"}]'::jsonb, '["a"]'::jsonb, 'Печериця польова росте на луках, пасовищах, галявинах, у садах — на відкритих місцях.', 'довідник: печериця польова', false, 'open'),
  ('forest_light', 'forest', 'single', 'Де в лісі білі гриби трапляються частіше?', '[{"id": "a", "text": "У темній гущавині"}, {"id": "b", "text": "На узліссях і галявинах"}, {"id": "c", "text": "Під густим ялинником"}, {"id": "d", "text": "У сирій низині біля болота"}]'::jsonb, '["b"]'::jsonb, 'Білий гриб не любить гущавини. Шукайте на узліссях, галявинах, уздовж стежок — там, де пробивається сонце.', 'довідник: білий гриб («Світлові зони»)', false, 'open'),
  ('forest_spring', 'forest', 'multi', 'Квітень, вирубка в лісі. Кого тут можна зустріти? Оберіть усе правильне.', '[{"id": "a", "text": "Сморчок"}, {"id": "b", "text": "Строчок"}, {"id": "c", "text": "Лисичку"}, {"id": "d", "text": "Груздь"}]'::jsonb, '["a", "b"]'::jsonb, 'Навесні ростуть сморчки (опушки, вирубки, сади) і строчки (хвойні ліси на піску). Строчок смертельно отруйний. Лисички й грузді — з липня.', 'довідник: сморчок звичайний, строчок звичайний, лисичка справжня, груздь справжній', false, 'open'),
  ('forest_tf_pech', 'forest', 'single', 'Правда чи міф: печериці ростуть тільки в лісі.', '[{"id": "a", "text": "Правда"}, {"id": "b", "text": "Міф"}]'::jsonb, '["b"]'::jsonb, 'Міф. Печериця польова — на луках і пасовищах. А отруйна печериця жовтошкіра трапляється в садах, парках і на газонах.', 'довідник: печериця польова, печериця жовтошкіра', false, 'open'),
  ('forest_groudz', 'forest', 'single', 'Яке місце найбільше любить груздь справжній?', '[{"id": "a", "text": "Вологий мох під березою"}, {"id": "b", "text": "Сухий пісок під молодою сосною"}, {"id": "c", "text": "Стовбури старих дубів"}, {"id": "d", "text": "Луки й пасовища"}]'::jsonb, '["a"]'::jsonb, 'Груздь справжній росте в березових і мішаних із березою лісах, у моховитих вологих місцях.', 'довідник: груздь справжній', false, 'open'),
  ('forest_tf_rings', 'forest', 'single', 'Правда чи міф: «відьмині кільця» з грибів бувають і в лісі, не лише на луках.', '[{"id": "a", "text": "Правда"}, {"id": "b", "text": "Міф"}]'::jsonb, '["a"]'::jsonb, 'Правда. Кільцями ростуть і лісові гриби: говорушка руда в листяних лісах, рядовка сіра — у хвойних.', 'довідник: говорушка руда, рядовка сіра', false, 'open')
