-- ============================================================================
-- Тести знань: модуль «Ліс і гриб» (forest) — ADR-023
-- ============================================================================
-- Згенеровано scripts/quiz/build_module.py з data/quiz/forest.json; читабельна версія — docs/quiz/forest.md.
-- Питання оновлюються (за id), прибрані з JSON — знімаються з публікації; модуль публікується.

ON CONFLICT (id) DO UPDATE SET
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, correct = EXCLUDED.correct,
  explanation = EXCLUDED.explanation, source = EXCLUDED.source, critical = EXCLUDED.critical,
  topic = EXCLUDED.topic, published = true, hidden_by_reports = false, updated_at = now();

UPDATE public.quiz_questions SET published = false, updated_at = now()
WHERE module_id = 'forest' AND id NOT IN ('forest_fruit', 'forest_tf_seeds', 'forest_tf_small', 'forest_group', 'forest_ring', 'forest_order_grow', 'forest_trade_gets', 'forest_trade_gives', 'forest_farm', 'forest_tf_cut', 'forest_multi_partner', 'forest_tf_truffle', 'forest_birch', 'forest_tf_larch', 'forest_young_pine', 'forest_white_trees', 'forest_odd_pine', 'forest_sand', 'forest_tf_stump', 'forest_tinder', 'forest_multi_wood', 'forest_tf_winter', 'forest_oyster_ground', 'forest_where_oyster', 'forest_tf_dead', 'forest_meadow', 'forest_light', 'forest_spring', 'forest_tf_pech', 'forest_groudz', 'forest_tf_rings');

UPDATE public.quiz_modules SET published = true, questions_per_attempt = 15 WHERE id = 'forest';
